#include <vector>

class Solution {
public:
    int minPatches(std::vector<int>& nums, int target) {
        long long miss = 1;
        int added = 0;
        int i = 0, n = nums.size();
        while (miss <= target) {
            if (i < n && nums[i] <= miss) {
                miss += nums[i];
                i++;
            } else {
                miss += miss;
                added++;
            }
        }
        return added;
    }
};

